func TestExtractor_MalformedTruncated_ReturnsErrMalformedFile_NoPanic(t *testing.T) {
	// The defer/recover in Extract.Extract must intercept any
	// library panic and convert to ErrLibraryPanic, OR the parser
	// must surface ErrMalformedFile cleanly. Either outcome is
	// acceptable; what's NOT acceptable is the test process
	// crashing.
	//
	// ErrNoMetadata joined the acceptable set in #765. This fixture is
	// the first half of a JPEG that never carried EXIF, so "valid
	// enough container, nothing extractable" is the honest verdict.
	// It used to come back nil only because the dimension sniff read
	// the still-intact SOF header and put two fields in the Result —
	// the extractor reported "I found metadata" about a file it had
	// found no metadata in. Removing that write made the outcome match
	// the file.
	_, err := extract(t, "malformed_truncated.jpg")
	if err == nil {
		// Some truncations are still partially decodable —
		// fine. The test's actual job is "no panic".
		t.Log("truncated file produced no error — unexpected but not failing")
		return
	}
	if !errors.Is(err, metadata.ErrMalformedFile) &&
		!errors.Is(err, metadata.ErrLibraryPanic) &&
		!errors.Is(err, metadata.ErrNoMetadata) {
		t.Errorf("got %v, want ErrMalformedFile, ErrLibraryPanic or ErrNoMetadata", err)
	}
}

func TestExtractor_LibraryPanic_RecoveredAsTypedError(t *testing.T) {
	// We can't easily induce a panic in dsoprea from a regular
	// fixture, but we CAN confirm the recover wrapper is in
	// place by passing nil bytes — which used to crash older
	// versions. Mostly a sanity check that the defer is wired.
	e := exif.New()
	_, err := e.Extract(context.Background(), bytes.NewReader(nil), "image/jpeg")
	// nil bytes → dsoprea ErrNoExif (graceful) → no metadata,
	// extractor returns ErrNoMetadata (no panic). What matters:
	// no panic propagated past Extract.
	if err == nil {
		t.Log("empty source returned nil error — acceptable")
		return
	}
	// Any error is fine here as long as the process didn't crash.
	t.Logf("empty source err: %v", err)
}
